"""Hand-authored L12 coverage after inspecting all 25 rendered pages."""
from authoring_helpers import DraftBatch,formula
b=DraftBatch('W03-L12',3,'L12','Recursive Newton–Euler dynamics',379,'robotics-integration-author-L12')
newton=formula('F=m a_C',{'F':'net external force on the link','m':'link mass','a_C':'center-of-mass acceleration'},{'F':'N','m':'kg','a_C':'m/s²'},['Constant-mass rigid link; all vector components share a basis.'])
euler=formula('N_C=I_C α+ω×(I_C ω)',{'N_C':'net external moment about the center of mass','I_C':'inertia tensor about the center of mass in body-aligned axes','α':'angular acceleration','ω':'angular velocity'},{'N_C':'N·m','I_C':'kg·m²','α':'rad/s²','ω':'rad/s'},['Rigid body; all terms use the same coordinate basis.'])
angular=formula('ω_next=R ω+qdot z; α_next=R α+(R ω)×(qdot z)+qddot z',{'R':'rotation from current-link to next-link coordinates','ω,α':'current-link angular velocity and acceleration','ω_next,α_next':'next-link quantities in next-link coordinates','qdot,qddot':'relative revolute rate and acceleration','z':'unit joint axis in next-link coordinates'},{'R,z':'dimensionless','ω,ω_next,qdot':'rad/s','α,α_next,qddot':'rad/s²'},['Revolute joint with fixed axis in the next-link frame.'])
accel=formula('a_C=a_O+α×r_C+ω×(ω×r_C)',{'a_C':'center-of-mass acceleration','a_O':'link-origin acceleration','r_C':'origin-to-center-of-mass offset fixed in the link','α':'link angular acceleration','ω':'link angular velocity'},{'a_C,a_O':'m/s²','r_C':'m','α':'rad/s²','ω':'rad/s'},['All terms expressed in one basis; rigid fixed offset.'])
inward=formula('f_i=F_i+R f_next; n_i=N_i+R n_next+r_C×F_i+p×(R f_next)',{'f_i,n_i':'proximal force and moment exerted on link i','F_i,N_i':'net inertial resultant force and center-of-mass moment','f_next,n_next':'distal transmitted force and moment in next-link coordinates','R':'rotation from next-link to current-link coordinates','r_C':'current-origin to center-of-mass vector in current coordinates','p':'current-origin to next-origin vector in current coordinates'},{'f_i,F_i,f_next':'N','n_i,N_i,n_next':'N·m','r_C,p':'m','R':'dimensionless'},['Use the lecture interlink-force convention; all sums/cross products are in current-link coordinates.'])
b.add(382,'formulations','Lagrange and Newton–Euler methods','Which comparison matches the two manipulator-dynamics formulations?', ['Lagrange starts from kinetic/potential energy; Newton–Euler applies translation/rotation balances link by link','Lagrange starts from force transmission; Newton–Euler avoids inertia by using geometry alone','Both methods use only end-effector position and omit acceleration','Newton–Euler is restricted to static equilibrium, while Lagrange alone handles motion'],0,'The lecture contrasts an energy-based formulation with linkwise Newton and Euler laws used recursively for inverse dynamics.', ['This preserves the methodological distinction.','Newton–Euler explicitly includes link inertia and acceleration.','Dynamics requires motion rates and inertial data, not only position.','Newton–Euler directly computes forces and torques for prescribed motion.'],typ='match',difficulty='easy')
b.add(383,'bond-graphs','Power exchange across domains','In bond-graph modeling, what do the directed half-arrows represent?', ['Power exchange between physical components across energy domains','Only data messages between software processes','A requirement that every modeled component be electrical','A kinematic joint angle without any energy interpretation'],0,'The bonds show power exchange, allowing different physical energy domains to share one modeling framework.', ['This is the stated purpose of the bonds.','Power exchange is physical, not merely software communication.','The method is explicitly multi-domain.','The arrow has a power-flow role, not just an angle label.'],typ='definition',difficulty='easy')
b.add([384,386,387],'rigid-inertial-parameters','What inertial parameters describe','Which qualification makes the slide’s “mass distribution is known completely” statement precise for rigid-body dynamics?', ['Mass, center of mass and inertia summarize the inertial properties needed here; they do not uniquely recover every density detail','Center of mass alone determines every rotational inertia tensor','The inertia tensor removes the need to know the total mass in F=m a_C','These parameters determine the full microscopic density field uniquely'],0,'The force law needs mass, and the rotational law needs center-of-mass inertia; these finite moments characterize equivalent rigid-body inertial behavior, not a unique density field.', ['This states the relevant scope without overclaiming a unique distribution.','Bodies with the same center of mass can have different inertias.','The translational force still depends on m.','Different density distributions can share the same mass moments.'],conflict='Physical page 384 says center-of-mass location and inertia make the mass distribution known completely, without explicitly listing mass or limiting the statement to rigid-body inertial behavior.')
b.add(385,'recursive-complexity','Linear-time recursive dynamics','If each link requires a fixed-size calculation in one outward and one inward pass, how does runtime scale with n links?', ['O(n), since two linear passes remain linear','O(n²), because multiplying the two pass counts gives n²','O(1), because the recursion uses the same equations at every link','O(2ⁿ), because the two directions create a binary branch at every link'],0,'Each pass visits each link once, so the work is c1 n+c2 n rather than a nested n-by-n calculation.', ['The sum of two linear costs is linear.','The passes are sequential rather than nested.','Repeated equations still require work for each link.','Changing traversal direction does not create a branching search tree.'],typ='derivation',assumptions=['A serial kinematic chain with fixed-size spatial vector/matrix operations per link.'],memory='Two passes add; they do not multiply.')
b.add(385,'dynamics-terms','Terms represented by the model','Select all effects explicitly listed for the Newton–Euler rigid-body model.', ['Inertial effects','Coriolis and centrifugal effects','Gravitational effects','Material fatigue life inferred without an additional material model'],[0,1,2],'The slide lists inertial, Coriolis, centrifugal and gravitational effects; fatigue behavior is not supplied by those rigid-body equations.', ['Acceleration and inertia contribute directly.','Velocity-dependent terms arise in rotating-link kinematics.','Gravity is included through the model.','Fatigue requires additional material and loading-history information.'],typ='statement',difficulty='easy')
b.add(386,'newton-force','Force and center-of-mass acceleration','A 3 kg link has center-of-mass acceleration (2,-1,0) m/s²; what net force is required?', ['(6,-3,0) N','(2/3,-1/3,0) N','(6,3,0) N','(3,-3,0) N'],0,'Multiply each acceleration component by the constant mass: F=(6,-3,0) N.', ['This applies F=m a_C componentwise.','This divides by mass instead of multiplying.','This loses the negative y acceleration.','The x component must include the factor 2.'],typ='numerical',difficulty='easy',formulas=[newton])
b.add(386,'newton-force','Reading the force sketch','In the Newton-law sketch, the force and acceleration arrows are attached to the marked center of mass; which interpretation is correct?', ['F is the net force and v̇_C is the acceleration of that center of mass','F is the joint position and v̇_C is its angular velocity','v̇_C is the velocity of the endpoint rather than a time derivative','The marker shows the proximal joint axis rather than the center of mass'],0,'The slide places the mass-center marker on the link and labels its acceleration v̇_C, linked to net force by F=m v̇_C.', ['This matches both the diagram and equation.','Force, position and angular velocity are different quantities.','The dot indicates acceleration, and C denotes the center of mass.','The center marker lies within the link, not at the proximal joint.'],typ='diagram',difficulty='easy')
b.add(387,'euler-moment','Euler moment and angular momentum','Which pair correctly identifies angular momentum about the mass center and the required moment?', ['H_C=I_Cω; N_C=I_Cα+ω×H_C','H_C=I_Cα; N_C=I_Cω+ω×H_C','H_C=m v_C; N_C=I_Cα only for every rotation','H_C=ω×I_Cω; N_C=H_C×α'],0,'I_Cω is angular momentum, and its inertial rate includes the transport term ω×I_Cω.', ['This is the source Euler equation.','This interchanges angular velocity and acceleration.','m v_C is linear momentum; the gyroscopic term need not vanish.','The cross term contributes to the moment, not the definition of H_C.'],typ='match',formulas=[euler])
b.add(387,'gyroscopic-term','When the gyroscopic term vanishes','Select all cases that guarantee ω×(I_Cω)=0 at that instant.', ['ω=0','ω is along a principal inertia axis','I_C is a scalar multiple of the identity','α=0 for an arbitrary non-principal ω'],[0,1,2],'The cross product is zero when angular momentum is parallel to angular velocity; this includes zero velocity, a principal axis or spherical inertia.', ['Zero angular velocity makes the cross product zero.','A principal-axis eigenvector gives I_Cω=λ ω.','A scalar inertia multiplies every direction without changing it.','Zero angular acceleration alone does not align ω and I_Cω.'],typ='derivation',formulas=[euler])
b.add(387,'euler-moment','A full Euler calculation','Let I_C=diag(2,3,4) kg·m², ω=(1,2,3) rad/s and α=(0.5,-1,2) rad/s² in the same body-aligned frame; what is N_C?', ['(7,-9,10) N·m','(1,-3,8) N·m','(-5,3,6) N·m','(6,-6,2) N·m'],0,'I_Cα=(1,-3,8), I_Cω=(2,6,12), and ω×I_Cω=(6,-6,2); adding gives (7,-9,10) N·m.', ['Both inertia and gyroscopic contributions are included.','This omits the gyroscopic term.','This subtracts rather than adds the gyroscopic term.','This includes only the gyroscopic contribution.'],typ='numerical',steps=['Compute I_Cα.','Compute H_C=I_Cω.','Compute ω×H_C with the right-hand cross-product order.','Add the two moment contributions.'],formulas=[euler])
b.add(388,'inverse-dynamics-inputs','Inputs and output of inverse dynamics','Which input/output description matches the lecture’s inverse-dynamics problem?', ['Joint positions, velocities, accelerations, kinematics and inertial data determine required joint efforts','Joint efforts alone determine the required end-effector pose without a model','Positions and link lengths alone determine effort for any speed profile','Joint accelerations are outputs rather than prescribed inputs in this problem'],0,'Inverse dynamics computes the efforts required for a specified instantaneous trajectory state and robot model.', ['This matches the listed input data and requested torques.','A model and state are needed, and this describes a different problem.','Different velocities and accelerations can change the required effort.','Acceleration is prescribed here; solving for acceleration is forward dynamics.'],typ='definition',difficulty='easy')
b.add([389,396,397],'pass-order','Outward and inward passes','Which sequence follows the recursive inverse-dynamics algorithm?', ['Propagate motion from base to tip, compute each inertial resultant, then propagate loads from tip to base','Propagate joint torques outward before any link acceleration is known','Compute only end-link acceleration and apply the same inertial force to every link','Alternate outward force and inward velocity passes without respecting their boundary data'],0,'The outward pass provides link accelerations and inertial loads; the inward pass then accumulates transmitted forces and moments.', ['This respects the dependencies and directions.','Each link’s inertial load depends on its acceleration.','Links have different masses and accelerations.','The recursions have distinct inputs and traversal directions.'],typ='sequence')
b.add(390,'angular-recursion','Revolute angular-velocity propagation','For R=I, inherited ω=(1,0,2) rad/s, qdot=3 rad/s and joint axis z=(0,0,1), what is ω_next?', ['(1,0,5) rad/s','(1,0,-1) rad/s','(0,0,3) rad/s','(4,3,5) rad/s'],0,'The relative revolute motion adds qdot z=(0,0,3) to the inherited angular velocity.', ['Both inherited and relative motion are included.','This subtracts the relative rate.','This discards inherited angular velocity.','The scalar joint rate contributes only along its axis.'],typ='numerical',difficulty='easy',formulas=[angular])
b.add(390,'angular-recursion','Transport term in angular acceleration','With R=I, ω=(1,0,0), α=(0,0,0), qdot=2 and qddot=3 about z=(0,0,1), what is α_next in rad/s²?', ['(0,-2,3)','(0,2,3)','(0,0,3)','(0,-4,3)'],0,'ω×(qdot z)=(1,0,0)×(0,0,2)=(0,-2,0); adding qddot z gives (0,-2,3).', ['This uses the transport cross term once.','This reverses the cross-product order.','This omits the transport term.','The factor 2 in linear Coriolis acceleration does not belong in this angular formula.'],typ='numerical',formulas=[angular])
b.add(390,'prismatic-angular','Correcting the prismatic derivative mismatch','The final prismatic line prints α_next=Rω; with no relative rotation across that joint, which expression is consistent?', ['α_next=Rα','α_next=Rω','α_next=Rα+qdot z','α_next=Rα+qddot z for the prismatic displacement'],0,'A prismatic joint contributes no relative angular motion, so angular acceleration is inherited through rotation; the printed right side is missing the time derivative.', ['This matches angular-acceleration units and the no-relative-rotation condition.','This repeats the source velocity/acceleration mismatch.','A linear prismatic rate cannot be added as angular acceleration.','A linear prismatic acceleration contributes to linear, not angular, acceleration.'],typ='source-reconciliation',formulas=[formula('α_next=Rα',{'α_next,α':'successive link angular accelerations','R':'coordinate rotation'},{'α_next,α':'rad/s²','R':'dimensionless'},['Prismatic joint; no relative angular motion.'])],conflict='Physical page 390, printed slide 12, writes a dotted angular velocity on the left but undotted ω on the right in the final prismatic line.')
b.add(391,'origin-acceleration','Tangential and centripetal terms','For a fixed offset p from one rigid-link origin to the next, which terms supplement the inherited origin acceleration before frame conversion?', ['α×p and ω×(ω×p)','ω×p and α×(α×p)','2ω×p and a relative sliding acceleration even when no sliding occurs','p×α and (ω×ω)×p'],0,'Differentiating the offset velocity adds tangential acceleration α×p and centripetal acceleration ω×(ω×p).', ['These are the two displayed rotational terms.','ω×p is velocity, while α×(α×p) has the wrong derivative order.','The Coriolis term requires relative sliding velocity.','The first term reverses sign, and ω×ω is zero.'],typ='derivation',formulas=[accel])
b.add(391,'center-acceleration','Numerical center-of-mass acceleration','A rigid link has a_O=(1,0,0) m/s², α=(0,0,3) rad/s², ω=(0,0,2) rad/s and r_C=(0.5,0,0) m in one basis; what is a_C?', ['(-1,1.5,0) m/s²','(3,1.5,0) m/s²','(-2,1.5,0) m/s²','(1,1.5,0) m/s²'],0,'The tangential term is (0,1.5,0), the centripetal term is (-2,0,0), and adding a_O gives (-1,1.5,0).', ['All three contributions are included.','This reverses the centripetal sign.','This omits origin acceleration.','This omits centripetal acceleration.'],typ='numerical',formulas=[accel])
b.add(391,'prismatic-linear','Sliding-joint acceleration additions','Which additional terms arise from a prismatic displacement d along the local unit axis z?', ['2ω_next×(d_dot z)+d_ddot z','ω_next×(d_dot z)+d_ddot z','2ω_next×(d_ddot z)+d_dot z','d_ddot z only, even when ω_next and d_dot z are nonparallel'],0,'The moving-point formula contributes a Coriolis term with factor 2 and the relative linear acceleration.', ['Both sliding terms and their orders are correct.','This loses one of the two transport contributions.','This interchanges velocity and acceleration roles.','The Coriolis term generally survives for nonparallel rotation and sliding.'],typ='derivation',formulas=[formula('a_extra=2ω×v_rel+a_rel',{'a_extra':'additional sliding acceleration','ω':'link angular velocity','v_rel':'relative sliding velocity d_dot z','a_rel':'relative sliding acceleration d_ddot z'},{'a_extra,a_rel':'m/s²','ω':'rad/s','v_rel':'m/s'})])
b.add(391,'prismatic-linear','A nonzero Coriolis contribution','If ω_next=(1,0,0) rad/s, d_dot=2 m/s, d_ddot=3 m/s² and z=(0,0,1), what are the added prismatic terms together?', ['(0,-4,3) m/s²','(0,-2,3) m/s²','(0,4,3) m/s²','(0,0,3) m/s²'],0,'2(1,0,0)×(0,0,2)=(0,-4,0), then add (0,0,3).', ['This includes the factor 2 and correct sign.','This omits the Coriolis factor 2.','This reverses the cross-product order.','This omits Coriolis acceleration.'],typ='numerical',formulas=[formula('a_extra=2ω_next×(d_dot z)+d_ddot z',{'ω_next':'link angular velocity','d_dot,d_ddot':'sliding speed and acceleration','z':'joint unit axis','a_extra':'additional acceleration'},{'ω_next':'rad/s','d_dot':'m/s','d_ddot,a_extra':'m/s²','z':'dimensionless'})])
b.add(392,'com-frame','Center-of-mass frame convention','How does frame C_i relate to link frame i in the inertial-load calculation?', ['Its origin is at the link center of mass and its axes have the same orientation as frame i','Its origin is at the next joint and its axes are always inertially fixed','It must be at the base so every link uses the same origin','Its axes must be principal axes even when frame i is not'],0,'The slide uses a translated center-of-mass frame with the same orientation as the link frame.', ['This is the explicit frame convention.','The source places its origin at the mass center.','Center-of-mass moments use each link’s own mass center.','Same orientation as frame i does not require diagonalizing inertia.'],typ='definition',difficulty='easy')
b.add([389,392,393],'resultant-versus-transmitted','Resultant and transmitted loads','In the link diagram, what distinguishes F_i,N_i from f_i,n_i?', ['F_i,N_i are net inertial resultants at/about the mass center; f_i,n_i are the proximal loads exerted by link i−1 on link i','Both pairs are identical joint-axis scalar efforts','F_i,N_i are distal-only loads while f_i,n_i are mass and inertia parameters','Uppercase denotes global coordinates and lowercase denotes a different physical law'],0,'The uppercase quantities follow Newton/Euler for the whole link; the lowercase quantities describe interlink transmission at the joint.', ['This preserves the physical roles and reference points.','They are vectors, and the net resultant need not equal one joint’s contribution.','The lowercase symbols are forces/moments, not inertial parameters.','Capitalization distinguishes physical quantities here, not coordinate frames.'],typ='diagram')
b.add(393,'force-balance','Why the distal force subtracts','Given f_next as the force link i exerts on link i+1, why is the link-i force balance F_i=f_i−R f_next?', ['The distal neighbor exerts the opposite reaction on link i, after both forces use the same basis','A coordinate rotation always negates the force vector','Forces from a higher numbered link must be ignored','The subtraction replaces the acceleration term rather than representing a reaction'],0,'Newton’s third law changes the distal action to its reaction; R changes its components into the current frame.', ['The minus sign is physical action/reaction, while R handles coordinates.','Rotation and action/reaction are separate operations.','The distal reaction contributes to link-i balance.','F_i remains the inertial resultant m_i a_Ci.'],typ='derivation',formulas=[inward])
b.add(393,'moment-arms','Moment arms about the center of mass','With r_C from origin i to the mass center and p from origin i to origin i+1, which lever arms are used about the mass center?', ['−r_C for the proximal joint and p−r_C for the distal joint','r_C for the proximal joint and p+r_C for the distal joint','p for both joints','r_C−p for the proximal joint and r_C for the distal joint'],0,'A moment arm starts at the chosen reference point, so subtract the mass-center position from each joint position.', ['Both vectors start at the center of mass and end at the relevant joint.','These signs and origins do not match the required differences.','The two joints have distinct offsets from the mass center.','These swap the relevant locations.'],typ='diagram')
b.add([393,394],'inward-recursion','Inward force and moment recursion','Which combination reproduces the displayed inward moment recursion in frame i?', ['N_i+R n_next+r_C×F_i+p×(R f_next)','N_i+R n_next−r_C×F_i−p×(R f_next)','N_i+n_next+r_C×F_i+p×f_next, without rotating next-frame data','R n_next+r_C×F_i, with the link inertial moment and distal-force arm omitted'],0,'The proximal moment balances the inertial moment, the distal transmitted moment and both moment-arm contributions in one common basis.', ['All four contributions and basis changes are present.','This reverses the two moment-arm terms after rearrangement.','Next-frame vectors require rotation before addition and cross products.','The omitted terms generally do not vanish.'],typ='derivation',formulas=[inward])
b.add(394,'inward-recursion','Cancellation in the moment derivation','After inserting f_i=F_i+R f_next into the mass-center moment balance, which pair cancels?', ['−r_C×(R f_next) and +r_C×(R f_next)','−r_C×F_i and +r_C×(R f_next) for every link','N_i and R n_next for every motion','p×(R f_next) and r_C×F_i for every mass distribution'],0,'Expanding −(p−r_C)×(R f_next) creates a positive r_C cross distal-force term that cancels the negative one from the proximal force substitution.', ['They are equal and opposite copies of the same vector cross product.','F_i and the distal force are different quantities.','The inertial and transmitted moments do not generally match.','Distinct moment arms and loads need not cancel.'],typ='derivation',steps=['Expand −r_C×(F_i+R f_next).','Expand −(p−r_C)×R f_next.','Cancel the opposite r_C×R f_next terms.'],formulas=[inward])
b.save();print(len(b.questions),'incremental L12 drafts')
b.add(394,'inward-recursion','Numerical force and moment accumulation','All vectors are in frame i and R=I: F_i=(0,2,0) N, N_i=(0,0,1) N·m, f_next=(0,3,0) N, n_next=(0,0,2) N·m, r_C=(0.5,0,0) m and p=(1,0,0) m; what are (f_i,n_i)?', ['((0,5,0) N, (0,0,7) N·m)','((0,5,0) N, (0,0,3) N·m)','((0,-1,0) N, (0,0,-1) N·m)','((0,5,0) N, (0,0,6) N·m)'],0,'Forces add to (0,5,0); the z moments are 1+2+0.5×2+1×3=7 N·m.', ['Both force and all four moment terms are included.','This omits both moment-arm contributions.','This subtracts the distal load after the recursion has already been rearranged.','This omits the center-of-mass force moment.'],typ='numerical',formulas=[inward])
b.add(394,'inward-recursion','Rotate loads before accumulation','Let R=Rz(90°), f_next=(2,0,0) N, n_next=(0,0,3) N·m, F_i=(0,1,0) N, N_i=(0,0,1) N·m, r_C=(0.5,0,0) m and p=(1,0,0) m; what is n_i?', ['(0,0,6.5) N·m','(0,0,4.5) N·m','(0,0,2.5) N·m','(0,0,6) N·m'],0,'R f_next=(0,2,0), R n_next=(0,0,3), so n_i,z=1+3+0.5+2=6.5.', ['This rotates distal force before the offset moment.','This omits the distal-force moment, which would also happen if its unrotated x force were used.','This uses the inverse rotation for the distal force.','This omits the mass-center offset contribution.'],typ='numerical',assumptions=['F_i, N_i, r_C and p are expressed in frame i; distal loads are expressed in frame i+1.'],formulas=[inward])
b.add(395,'joint-projection','Revolute and prismatic effort','Which joint-axis projection is correct?', ['Revolute: n_i·z_i in N·m; prismatic: f_i·z_i in N','Revolute: f_i·z_i in N; prismatic: n_i·z_i in N·m','Both joint types use n_i·z_i because the generic effort symbol is τ','Both joint types use the magnitude of the complete transmitted wrench'],0,'A rotational coordinate is driven by its axial moment, whereas a sliding coordinate is driven by its axial force.', ['This preserves the mechanical variable and its units.','This swaps the joint types.','The generic symbol does not force prismatic effort to have torque units.','Projection retains sign and only the component conjugate to the joint motion.'],typ='match',difficulty='easy',traps=['Do not call a prismatic generalized effort a torque merely because the slide writes τ.'])
b.add(395,'joint-projection','Axis component rather than vector magnitude','For z=(0,0,1), n_i=(3,4,-2) N·m and f_i=(5,-1,6) N, what are the revolute and prismatic efforts, respectively?', ['-2 N·m and 6 N','√29 N·m and √62 N','2 N·m and -6 N','6 N·m and -2 N'],0,'Dotting each vector with the positive z axis selects its signed z component.', ['This uses the required projections.','These are vector magnitudes rather than signed axial components.','This reverses both axis signs.','This swaps force and moment roles.'],typ='numerical',difficulty='easy')
b.add([396,397],'pass-indices','Six-joint loop indices','Why do the summary loops use outward i=0…5 and inward i=6…1?', ['The outward formula computes link i+1, while the inward formula computes link i for a six-link example','Every robot must have exactly six links for Newton–Euler to work','The outward loop leaves link 6 uncomputed','The inward loop computes only five links because its endpoint is 1'],0,'Outward i=0 generates link 1 and i=5 generates link 6; inward then visits links 6 through 1.', ['The indexing matches each recursion’s target link.','The algorithm generalizes to n links with appropriate bounds.','The final outward iteration targets link 6.','The inclusive sequence 6,5,4,3,2,1 has six links.'],typ='algorithm_trace',difficulty='easy',assumptions=['Use the six-joint example shown in the slides, not a claim that all manipulators have six joints.'])
b.add([396,397],'pass-dependencies','A free terminal boundary','For a free terminal link with no applied end wrench, which initialization is consistent before the inward pass?', ['Set the downstream terminal force and moment to zero, while retaining the last link’s own inertial F and N','Set every link’s F and N to zero regardless of acceleration','Set all proximal forces to zero before computing the last link','Remove the last link’s center-of-mass moment arm because the endpoint is free'],0,'A free endpoint has no transmitted terminal load, but the last link still requires effort to produce its own acceleration.', ['This separates external boundary loading from inertial loading.','Acceleration and inertia can produce nonzero resultants despite a free endpoint.','Proximal transmission is the unknown result of the inward recursion.','The center-of-mass load can still have a moment about the joint.'],typ='scenario',formulas=[inward],assumptions=['No external terminal wrench; rigid links can still have nonzero accelerations.'])
b.add(398,'gravity-initialization','Sign of the fictitious base acceleration','Physical gravity in base coordinates is g_phys=(0,0,-9.81) m/s²; what base acceleration initializes the gravity-compensation recursion for a stationary base?', ['(0,0,+9.81) m/s²','(0,0,-9.81) m/s²','(0,0,0) m/s² while omitting all gravity terms','(0,0,+19.62) m/s²'],0,'The fictitious acceleration is opposite the physical gravitational acceleration: a_0=-g_phys.', ['This matches the source convention.','This uses the physical-gravity direction rather than its opposite.','Zero initialization without another gravity term omits gravity.','Only one g is required, not two.'],typ='numerical',difficulty='easy',formulas=[formula('a_0=-g_phys',{'a_0':'fictitious base acceleration used in inverse dynamics','g_phys':'physical gravitational acceleration in base coordinates'},{'a_0,g_phys':'m/s²'},['Physically stationary base; gravity included by this initialization rather than a second separate gravity load.'])])
b.add(398,'gravity-initialization','Fictitious does not mean actual base motion','What does setting the computational base acceleration to an upward 1 g mean?', ['It is a bookkeeping device that yields the required gravity-balancing efforts without physically moving the base','The controller must accelerate the laboratory floor upward before every calculation','Gravity is canceled physically and the links lose their weight','Every joint must move upward at a constant speed of 1 m/s'],0,'The initialization reuses the existing inertial recursion to account for gravity; it does not prescribe an actual base trajectory.', ['This distinguishes the computational equivalent from physical motion.','The actual base can remain stationary.','The gravitational load remains and must be balanced.','Acceleration and velocity are different quantities, and the joint motion is not prescribed by this trick.'],typ='conceptual',difficulty='easy')
b.add(398,'gravity-initialization','Avoiding double-counted gravity','A model already uses a_0=-g_phys to include gravity; what must be checked before separately adding a gravity-compensation vector g(q)?', ['Whether the returned effort already contains gravity, to avoid counting the same load twice','Whether the links have zero mass, since gravity only affects massless links','Whether the number of links is even, since only those chains double-count','Whether acceleration is measured in degrees rather than radians'],0,'The initialization already creates the gravitational contribution; adding the same compensation again would duplicate it.', ['This checks the physical content of the returned torque vector.','Gravitational loading scales with mass rather than being confined to massless links.','Parity of link count does not control double counting.','The issue is load accounting, not angle-unit conversion.'],typ='scenario')
b.add(398,'gravity-initialization','Single-link gravity moment','A stationary 2 kg link has center-of-mass offset r_C=(0.5,0,0) m from a z-axis revolute joint; physical gravity is (0,-9.81,0) m/s² in the same basis; what holding torque does the gravity-initialized recursion give?', ['+9.81 N·m about z','-9.81 N·m about z','+19.62 N·m about z','0 N·m because angular acceleration is zero'],0,'The fictitious acceleration is (0,+9.81,0), producing F=(0,19.62,0) N and r_C×F=(0,0,9.81) N·m.', ['This balances the negative gravitational moment.','This is the gravitational-load moment, not the opposing holding torque.','This omits the 0.5 m lever arm.','Gravity can require static torque despite zero actual angular acceleration.'],typ='numerical',assumptions=['No terminal wrench; no other loads; positive joint direction is +z.'],formulas=[newton,inward])
b.add(399,'ai-physics-prior','Physics prior and residual learning','Which pairing matches the slide’s AI integration ideas?', ['A physics-informed model incorporates Newton–Euler structure; residual learning models what the nominal dynamics misses','A physics prior means ignoring mechanics until all data are collected','Residual learning requires discarding the nominal model and learning every force from scratch','Embedding mechanics proves every learned controller is safe without testing'],0,'The slide distinguishes using physical structure from learning residual errors, both of which can complement a nominal dynamics model.', ['This captures the two stated roles.','A physics prior deliberately uses mechanics.','The slide’s residual approach retains the model.','A model structure alone is not a safety proof.'],typ='match')
b.add(399,'ai-data-claim','Scope of the numerical AI claim','The slide claims that embedding Newton–Euler structure can reduce data needs by what amount, and what evidence limit applies?', ['10–100×, stated as a slide claim without a study or universal guarantee on that page','10–100×, proven for every robot and training distribution by the equation alone','2×, measured experimentally in the displayed table','1000×, guaranteed whenever a model has an inertia tensor'],0,'The box prints 10–100×, but this page provides no experimental protocol, data or citation supporting a universal factor.', ['This reports the exact figure without treating it as independently established.','The page does not establish universality.','The stated range is different and no such results table is shown.','Neither the range nor the guarantee appears.'],typ='source-reconciliation',difficulty='easy',conflict='Physical page 399 states a 10–100× reduction in data needs without supporting study details on the page.')
b.add(399,'parameter-identification','Known regressor and unknown parameters','In τ=W(q,qdot,qddot)φ, which quantity is learned in the slide’s parameter-identification description?', ['The inertial parameter vector φ, using the known regressor W built from measured motion','The joint coordinate q, while τ and W are discarded','Only the sign of gravity, with all mass and inertia already known','A new Jacobian J that replaces the torque measurements'],0,'W depends on known motion variables and φ contains unknown inertial parameters to be estimated from data.', ['This is the stated known-regressor/unknown-parameter split.','Motion data form the regressor rather than being the unknown inertial vector.','The described unknowns include mass/inertia parameters.','The equation is a dynamics regressor, not a Jacobian replacement.'],typ='definition',formulas=[formula('τ=W(q,qdot,qddot)φ',{'τ':'joint-effort observations','W':'known dynamics regressor for the observed motion','φ':'unknown inertial parameter vector','q,qdot,qddot':'joint position, velocity and acceleration'},{'τ':'N·m for revolute joints; N for prismatic joints','φ':'mixed inertial-parameter units','W':'units matched columnwise to φ','q,qdot,qddot':'joint-type-specific position/rate/acceleration units'})])
b.add(399,'impedance-control','Interpreting the impedance terms','For τ=g(q)+Jᵀ[K_s(x_d−x)+B_s(v_d−v)], what roles do K_s and B_s play?', ['Stiffness-like gain on position error and damping-like gain on velocity error','Mass gain on position error and inertia tensor on velocity error','A rotation matrix and a translation vector','Two identical gains that both multiply acceleration error'],0,'The source pairs K_s with displacement error and B_s with velocity error inside a task-space force term.', ['This follows the two error terms.','The formula is not multiplying acceleration by mass.','These are control gains rather than a pose transform.','The two errors and gain roles differ.'],typ='match',assumptions=['Use consistent task-coordinate units and the slide’s idealized control expression; the label “Safe HRI” alone is not a safety guarantee.'])
b.add(399,'impedance-control','One-coordinate impedance calculation','In a one-coordinate example, g=2 N·m, J=0.5 m/rad, K_s=100 N/m, B_s=10 N·s/m, position error=0.02 m and velocity error=-0.1 m/s; what is τ?', ['2.5 N·m','3.5 N·m','1.5 N·m','0.5 N·m'],0,'The task force is 100×0.02+10×(-0.1)=1 N; Jᵀ gives 0.5 N·m and gravity compensation adds 2 N·m.', ['Both signed error terms and gravity are included.','This treats the negative velocity error as positive.','This subtracts the task torque rather than adding it.','This omits the gravity term.'],typ='numerical',formulas=[formula('τ=g+J(K_s e_x+B_s e_v)',{'τ':'joint torque','g':'gravity-compensation torque','J':'scalar task Jacobian','K_s':'stiffness gain','B_s':'damping gain','e_x,e_v':'position and velocity errors'},{'τ,g':'N·m','J':'m/rad','K_s':'N/m','B_s':'N·s/m','e_x':'m','e_v':'m/s'},['Scalar translational task and one revolute joint; coherent sign convention.'])])
b.add(399,'sim-to-real','Domain randomization versus learned inverse dynamics','Which statement matches the two distinct training ideas?', ['Randomize mass/inertia for sim-to-real training; train an inverse model to map (q,qdot,qddot) to τ','Randomize only image colors because dynamics parameters must never vary','Train the inverse model to map τ to qddot and call that the same input/output direction','Replace torque targets with link names because a symbolic model is unnecessary at inference'],0,'The slide associates sim-to-real with inertial-parameter variation and learned inverse dynamics with a motion-state-to-effort mapping.', ['This preserves both stated roles.','The slide explicitly mentions randomizing mass/inertia.','Effort-to-acceleration is the forward-dynamics direction.','A learned output still needs the appropriate effort target.'],typ='match')
b.add(400,'software-associations','Toolbox and KDL slide associations','According to the software slide, which pair of associations is stated?', ['Peter Corke Robotics Toolbox: MATLAB/Python and DH-oriented educational simulation; ROS2 + MoveIt row: KDL recursive Newton–Euler','Peter Corke Robotics Toolbox: Python/JAX only; ROS2 + MoveIt row: no rigid-body dynamics library','Peter Corke Robotics Toolbox: only a CAD package; KDL: image classification','Peter Corke Robotics Toolbox: reinforcement-learning policy only; MoveIt: only a plotting package'],0,'These are associations printed in the source software table, not a current-version feature audit.', ['This reproduces the two labeled rows.','The language tags and KDL mention contradict this alternative.','The source labels concern robotics dynamics, not those roles.','The table does not describe either tool that way.'],typ='table',difficulty='easy',assumptions=['Answer the source table’s associations; no claim of current version support or comparative superiority is made.'])
b.add(400,'software-associations','Pinocchio and differentiable dynamics rows','Which source-table pairing is correct?', ['Pinocchio lists Newton–Euler, ABA and CRBA; the Brax row emphasizes differentiable dynamics for gradient-based optimization','Pinocchio is listed as MATLAB only; Brax is listed as C++ only','Pinocchio is described solely as a sensor driver; Brax as a document editor','Both rows describe only static image datasets rather than dynamics tools'],0,'The Pinocchio row lists three rigid-body algorithms, while the Python/JAX Brax row emphasizes differentiability.', ['This matches both source rows.','The printed language tags are C++/Python and Python/JAX.','Those functions are absent from the two descriptions.','Both descriptions concern dynamics.'],typ='table',difficulty='easy',assumptions=['These are slide-attributed descriptions, not independently checked current implementation claims.'])
b.add(400,'software-associations','Simulation and multibody-control rows','Which descriptions does the source associate with PyBullet/MuJoCo and Drake, respectively?', ['Physics simulators for RL environments; multibody dynamics and model-predictive control','Symbolic-only algebra tools; a sensor-calibration spreadsheet','Only path-planning graph search; only neural-network image labeling','A messaging protocol; a robot operating-system distribution'],0,'The source pairs the simulators with RL training and Drake with multibody dynamics plus MPC research.', ['This matches the two stated roles.','The rows do not describe those limited roles.','These are not the functions listed.','Neither row is labeled as that infrastructure.'],typ='table',difficulty='easy',assumptions=['Source-table association only; broad internal-algorithm and superiority claims are not treated as externally verified.'])
b.add(401,'matrix-dynamics','Meaning of the matrix dynamics form','For τ=M(q)qddot+C(q,qdot)qdot+g(q), which interpretation is correct?', ['M multiplies acceleration, Cqdot collects velocity-dependent effects, and g gives gravity loading','M multiplies position directly, while g is the geometric Jacobian','Cqdot is the joint-position vector and contains no velocity effect','The equation omits gravity because recursive methods cannot include it'],0,'The matrix form organizes inertial, velocity-dependent and gravitational contributions to generalized effort.', ['This matches the variables and their roles.','The first input is acceleration, and g is gravity loading.','The term explicitly depends on joint velocity.','Gravity appears in g(q) and can also be included recursively.'],typ='match',formulas=[formula('τ=M(q)qddot+C(q,qdot)qdot+g(q)',{'τ':'generalized joint effort','M':'joint-space inertia matrix','Cqdot':'velocity-dependent generalized effort','g':'gravity generalized effort','q,qdot,qddot':'joint position, velocity and acceleration'},{'τ,Cqdot,g':'N·m for revolute joints; N for prismatic joints','M':'inertia units appropriate to its joint-coordinate pair','q,qdot,qddot':'joint-type-specific position/rate/acceleration units'},['Ideal rigid-body model shown; extra friction/contact terms require their own specified modeling.'])])
b.add([398,401],'matrix-dynamics','Static limit of the displayed dynamics','For a stationary configuration with qdot=0 and qddot=0 and no additional applied loads, what does the displayed equation reduce to?', ['τ=g(q)','τ=0 for every robot orientation','τ=M(q)q','τ=C(q,0) even without multiplication by qdot'],0,'The acceleration term and Cqdot term vanish, leaving the gravity-compensation effort.', ['This is the direct static limit.','Gravity need not vanish at a stationary configuration.','Position does not replace acceleration in the inertial term.','The displayed velocity-dependent term includes qdot, which is zero.'],typ='derivation',difficulty='easy')
b.add([385,399,401],'ai-model-role','What mechanics contributes to AI','Select all source-supported ways to combine Newton–Euler mechanics with learning.', ['Learn residual dynamics beyond a nominal model','Estimate unknown inertial parameters from motion and effort data','Use the model to generate training data for a learned inverse map','Treat a physics model as proof that no validation is needed after deployment'],[0,1,2],'The source lists residual learning, parameter identification and learned inverse dynamics; none removes the need to validate the resulting system.', ['This preserves known mechanics and learns mismatch.','This is the regressor-based identification idea.','The slide describes a neural inverse model trained on Newton–Euler data.','A physical model can still be incomplete or mismatched to the real system.'],typ='statement')
b.save();print(len(b.questions),'L12 draft questions;',len(b.concepts),'concept records; independent review pending')
